    discover: [
      B.text('075_d_intro', 'Kontroll 15', 'See leht kordab mooduli 15 mustreid: tulevik olevikuga ja hakkama-ga, soovid ja eesmärgid, kui-laused ning põhjendatud plaan. Tee kõik ilma abita.'),
      B.categorize('075_d_sort', 'Mooduli sõnad.', 'Sorteeri sõnad.', [['Aeg', ['homme', 'järgmisel aastal', 'varsti', 'tulevikus']], ['Soov ja eesmärk', ['soovin', 'plaanin', 'loodan', 'eesmärk']], ['Tingimus', ['kui', 'siis', 'kui ei', 'mis siis, kui']], ['Põhjendus', ['esiteks', 'teiseks', 'näiteks', 'sellepärast']]]),
      B.reading('075_d_read', 'Loe iseseisvalt.', 'Loe tekst ja vasta küsimustele.', 'Mihkli suur plaan',
        'Mihkel on kakskümmend viis aastat vana. Ta töötab praegu poes müüjana. Aga tal on suur plaan. Järgmisel aastal hakkab ta õppima kokaks. Tema eesmärk on avada kunagi oma kohvik. Mihkel armastab süüa teha juba lapsest saadik. Kokakool kestab kaks aastat. Selleks peab ta töölt lahkuma või vähem töötama. Mihkel plaanib töötada nädalavahetustel. Nii saab ta õppida ja raha teenida. Kui ta saab kooli sisse, siis kolib ta Tallinnasse. Kui ei saa, proovib ta uuesti järgmisel aastal. Esiteks on kokakool odavam kui ülikool. Teiseks saab ta praktikat teha päris restoranides. Näiteks tema sõber leidis praktika ajal endale töökoha. Mihkli ema on natuke mures. Ta arvab, et kohvik on riskantne. Aga Mihkel loodab, et kui ta töötab kõvasti, siis kõik õnnestub. Ta usub, et unistused täituvad.',
        [['Kuidas saab Mihkel õppida ja samal ajal raha teenida?', 'töötab nädalavahetustel|töötades nädalavahetustel|töötada nädalavahetustel'], ['Mis on tema eesmärk?', 'avada oma kohvik|avada kunagi oma kohvik|oma kohvik'], ['Kui kaua kokakool kestab?', 'kaks aastat'], ['Mida ta teeb, kui saab kooli sisse?', 'kolib Tallinnasse'], ['Mis on esimene põhjus?', 'kokakool on odavam kui ülikool'], ['Miks on ema mures?', 'kohvik on riskantne']]),
      B.notice('075_d_notice', 'Viimane pilk.', ['Järgmisel aastal **hakkab** ta kokaks **õppima**.', 'Tema **eesmärk on avada** oma kohvik.', '**Kui** ta saab kooli sisse, (siis) **kolib** ta Tallinnasse.', '**Esiteks** … **teiseks** … **näiteks** … **sellepärast** …'], 'full'),
      B.gaps('075_d_gaps', 'Kontrollitud osa.', 'Kirjuta sulgudes oleva verbi õige vorm.', ['Järgmisel aastal [hakkab] (hakkama) ta õppima.', 'Tema eesmärk on [avada] (avama) kohvik.', 'Kui ta [saab] (saama) kooli, kolib ta.', 'Ta plaanib [töötada] (töötama) nädalavahetustel.', 'Ma loodan, et kõik [õnnestub] (õnnestuma).', 'Kui sajab, [jääme] (jääma) me koju.']),
      B.transformation('075_d_trans', 'Ütle teisiti.', 'Kirjuta lause antud sõnaga.', [['Ma tahan kohvikut avada.', 'minu eesmärk on', 'Minu eesmärk on avada kohvik.; Minu eesmärk on kohvik avada.'], ['Ma õpin kokaks. (järgmisel aastal)', 'hakkan', 'Järgmisel aastal hakkan ma kokaks õppima.; Järgmisel aastal hakkan kokaks õppima.; Ma hakkan järgmisel aastal kokaks õppima.'], ['Ma saan kooli. Ma kolin.', 'kui', 'Kui ma saan kooli, kolin ma.'], ['Võib-olla õnnestub.', 'loodan', 'Ma loodan, et õnnestub.'], ['See on odavam. Esimene põhjus.', 'esiteks', 'Esiteks on see odavam.; Esiteks see on odavam.']]),
      B.truefalse('075_d_tf', 'Õige või vale?', 'Loe teksti uuesti.', [['Mihkel õpib praegu kokaks.', false], ['Kokakool kestab kaks aastat.', true], ['Mihkel plaanib töötada nädalavahetustel.', true], ['Kui ta kooli ei saa, loobub ta.', false], ['Ema on kohviku pärast mures.', true]]),
      B.wordforms('075_d_forms', 'Kordamine.', 'Kirjuta nõutud vorm.', [['hakkama', 'tema, olevik', 'hakkab'], ['avama', 'eesmärk on … (da-vorm)', 'avada'], ['lootma', 'mina, olevik', 'loodan'], ['sadama', 'kui homme … (olevik)', 'sajab'], ['õppima', 'tema, olevik', 'õpib'], ['töötama', 'plaanib … (da-vorm)', 'töötada']]),
      B.speaking('075_d_say', 'Soojendus.', 'Räägi 1 minut ilma abita: üks plaan, üks eesmärk ja üks kui-lause.', ['Mida sa homme teed?', 'Mis on sinu eesmärk?', 'Mis siis, kui…?'], [60, 90]),
      W('075_d_write', 'Minu suur plaan.', 'Kirjuta 8–10 lauset: üks suur plaan, eesmärk, kui-lause ja põhjused.', ['hakkan', 'eesmärk', 'kui', 'esiteks']),
      TR('075_d_tr', ['В следующем году он начнёт учиться на повара.', 'Его цель — открыть своё кафе.', 'Если он поступит, он переедет в Таллинн.', 'Во-первых, это дешевле.', 'Он надеется, что всё получится.']),
      D('075_d_dict', ['Järgmisel aastal hakkab ta õppima.', 'Tema eesmärk on avada kohvik.', 'Kui ta saab kooli, kolib ta.', 'Esiteks on see odavam.', 'Ta loodab, et kõik õnnestub.']),
      B.wordorder('075_d_order', 'Pane lause kokku.', 'Kirjuta laused õigesti.', ['Järgmisel aastal hakkab Mihkel kokaks õppima.', 'Tema eesmärk on avada oma kohvik.', 'Kui ta saab kooli sisse, kolib ta Tallinnasse.', 'Esiteks on kokakool ülikoolist odavam.', 'Mihkel loodab, et kõik õnnestub.']),
      B.selfcheck('075_d_self', ['Ma tean mooduli mustreid.', 'Ma moodustan kui-lause.', 'Ma tean, mida korrata.', 'Olen valmis kontrolliks.'], 'Valmis'),
    ],
